package com.smartspend.model;
import java.time.LocalDateTime;
public class Notification { private int id,userId; private String title,message,type; private boolean read; private LocalDateTime createdAt;
 public Notification(){} public Notification(int id,int userId,String title,String message,String type,boolean read,LocalDateTime createdAt){this.id=id;this.userId=userId;this.title=title;this.message=message;this.type=type;this.read=read;this.createdAt=createdAt;}
 public int getId(){return id;} public void setId(int v){id=v;} public int getUserId(){return userId;} public void setUserId(int v){userId=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getType(){return type;} public void setType(String v){type=v;} public boolean isRead(){return read;} public void setRead(boolean v){read=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;}}
